package vn.nanase.hako;
import android.app.Instrumentation;
import android.os.*;
import android.view.*;
import android.widget.*;
import android.content.*;
import java.util.*;
/** Measured Android layouts and actual MotionEvents, not source-string assertions. */
public final class PagedInteractionTest extends Instrumentation {
 int checks;void check(boolean condition,String why){checks++;if(!condition)throw new AssertionError(why);}
 // Unattached fixtures need an explicit root measure pass for requestLayout
 // issued during layout; an attached ViewRoot schedules that deferred pass.
 void layout(View view){for(int n=0;n<5;n++){view.forceLayout();view.measure(View.MeasureSpec.makeMeasureSpec(480,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(500,View.MeasureSpec.EXACTLY));view.layout(0,0,480,500);}}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();runOnMainSync(()->{
  LinearLayout rows=new LinearLayout(c);rows.setOrientation(1);for(int n=0;n<4;n++){Button row=new Button(c);row.setText("Control "+n);rows.addView(row,new LinearLayout.LayoutParams(-1,110));}
  TextView longText=new TextView(c);longText.setTextSize(20);StringBuilder content=new StringBuilder();for(int n=0;n<90;n++)content.append("Paragraph "+n+": complete content continues on the next page.\n");longText.setText(content);rows.addView(longText);Button finalRow=new Button(c);finalRow.setText("Last control");rows.addView(finalRow,new LinearLayout.LayoutParams(-1,110));
  EinkScrollView pages=new EinkScrollView(c);pages.addView(rows);layout(pages);int count=pages.pageCount();check(count>5,"Long metadata has multiple pages");ArrayList<Integer> offsets=new ArrayList<>();offsets.add(0);
  for(int n=1;n<count;n++){pages.turn(1);check(pages.page()==n,"Forward key reaches exactly one page: expected="+n+", actual="+pages.page()+", y="+pages.getScrollY()+", count="+pages.pageCount());int y=pages.getScrollY();check(y>offsets.get(n-1)&&y-offsets.get(n-1)<=500,"No skipped viewport");if(y>longText.getTop()&&y<longText.getBottom()){int local=y-longText.getTop()-longText.getTotalPaddingTop();boolean boundary=false;for(int line=0;line<longText.getLineCount();line++)if(local==longText.getLayout().getLineTop(line))boundary=true;check(boundary,"Long text starts at a whole line");}offsets.add(y);}
  pages.turn(1);check(pages.page()==count-1,"End does not wrap");for(int n=count-2;n>=0;n--){pages.turn(-1);check(pages.getScrollY()==offsets.get(n),"Back restores exact page boundary");}
  for(int n=0;n<20;n++)check(pages.pageCount()==count,"Repeated queries do not grow padding or page count");
  longText.setTextSize(28);layout(pages);check(pages.pageCount()>count,"Larger font recalculates pages: before="+count+", after="+pages.pageCount()+", textHeight="+longText.getHeight());
  c.getSharedPreferences("settings",0).edit().putBoolean("eink_mode",true).commit();PagedBookList books=new PagedBookList(c);books.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_list_item_1,Arrays.asList(content.toString(),"Second book","Third book")){public View getView(int position,View recycled,ViewGroup parent){TextView text=(TextView)super.getView(position,recycled,parent);text.setTextSize(20);text.setLayoutParams(new android.widget.AbsListView.LayoutParams(-1,books.rowHeight(position)));books.fitCard(text);return text;}});layout(books);check(books.getChildAt(0).getHeight()>500,"Long title remains complete rather than ellipsized");books.turn(1);layout(books);check(books.getFirstVisiblePosition()==0&&books.getChildAt(0).getTop()<0,"Oversized list row continues on the next page");books.turn(-1);layout(books);check(books.getFirstVisiblePosition()==0&&books.getChildAt(0).getTop()==books.getPaddingTop(),"Back restores oversized row offset exactly");
  SharedPreferences prefs=c.getSharedPreferences("settings",0);prefs.edit().putBoolean("eink_mode",false).putBoolean("reader_scroll",true).putBoolean("reader_swipes",true).commit();final int[] chapter={0};NativeReader reader=new NativeReader(c,c.getFilesDir(),new NativeReader.Listener(){public void position(int p,float f,int page,int total){}public void boundary(int d){}public void toolbar(){}public void dismissToolbar(){}public void chapter(int d){chapter[0]+=d;}});reader.style(22,10,1.3f,8,9,android.graphics.Typeface.SERIF,true);reader.layout(0,0,1000,1600);
  swipe(reader,300,700,700,710);check(chapter[0]==1,"Rightward swipe advances chapter in scroll mode");swipe(reader,700,700,300,710);check(chapter[0]==0,"Leftward swipe returns chapter");swipe(reader,300,1000,320,400);check(chapter[0]==0,"Vertical reading does not change chapter");swipe(reader,1,700,700,710);check(chapter[0]==0,"OS back edge does not change chapter");reader.setTouchLocked(true);swipe(reader,300,700,700,710);check(chapter[0]==0,"Touch lock suppresses chapter gesture");
 });sharedResume(c);profileAndRetention(c);result.putString("stream","PASS TOTAL "+checks+" paged interaction checks\n");finish(0,result);}catch(Throwable error){result.putString("stream","FAIL "+error+"\n");error.printStackTrace();finish(1,result);}}
 void sharedResume(Context c)throws Exception{
  c.getSharedPreferences("server_bridge",0).edit().clear().commit();ServerBridge.activeBook="";
  Store store=Store.get(c);String bid="truyen-999888",url="https://docln.sbs/truyen/999888-fixture";
  check(store.book(bid)==null,"Receiver starts without the source book");
  org.json.JSONObject data=new org.json.JSONObject().put("book",new org.json.JSONObject().put("id",bid).put("title","Remote only book").put("url",url)).put("chapters",new org.json.JSONArray().put(new org.json.JSONObject().put("id",bid+"-1").put("title","Chapter one").put("url",url+"/c1-first")).put(new org.json.JSONObject().put("id",bid+"-2").put("title","Chapter two").put("url",url+"/c2-second"))).put("read",new org.json.JSONArray().put(bid+"-1")).put("availability",new org.json.JSONObject().put("stored",2).put("total",2).put("complete",true)).put("position",new org.json.JSONObject().put("book",bid).put("chapter",bid+"-c2").put("revision",1).put("device","other-device").put("portable",new org.json.JSONObject().put("paragraph",12).put("fraction",0.3).put("last_read_at",System.currentTimeMillis()).put("visits",1)));
  ServerBridge.apply(c,data,true);check(store.book(bid)!=null&&store.chapters(bid).size()==2,"Shared metadata creates a missing book and its catalog");
  check(store.book(bid).current.equals(bid+"-2")&&store.book(bid).pos==12,"Missing-book import preserves the remote chapter and anchor");
  check(store.unread(bid)==1,"Read and remaining counts come from shared chapter IDs");
  check(store.downloadsSuppressed(bid),"Imported metadata alone never authorizes background chapter downloads");store.allowDownloads(bid);check(!store.downloadsSuppressed(bid),"Opening the imported book explicitly permits its reading batch");
  check(!store.chapter(bid,bid+"-2").ready&&!store.html(bid+"-2").exists(),"Remote cache metadata does not pretend local offline content exists");
  UiLibrarySnapshot snapshot=UiLibrarySnapshot.load(store,c.getSharedPreferences("settings",0));UiLibrarySnapshot.Summary summary=snapshot.summary(store.book(bid));
  check(summary.sharedComplete&&summary.sharedStored==2&&summary.stored==0,"Remote saved state and actual local downloads remain distinct");snapshot.prepareIndices();check(snapshot.index(3).stream().anyMatch(b->b.id.equals(bid)),"Saved-on-other-device book appears in the shared saved list");
  java.util.List<HakoParser.Link> active=java.util.Arrays.asList(new HakoParser.Link(bid+"-1","Chapter one",url+"/c1-first"),new HakoParser.Link(bid+"-2","Chapter two",url+"/c2-second"));java.util.List<HakoParser.Link> archived=new java.util.ArrayList<>(active);archived.add(new HakoParser.Link(bid+"-3","Retained old chapter",url+"/c3-old"));store.catalog(bid,archived);store.catalog(bid,active);check(store.chapter(bid,bid+"-3")!=null&&store.isHidden(bid,bid+"-3"),"Disappeared chapter metadata is retained");check(store.unread(bid)==1&&UiLibrarySnapshot.load(store,c.getSharedPreferences("settings",0)).summary(store.book(bid)).total==2,"Retained hidden chapters do not change shared active-catalog counts");
  c.getSharedPreferences("settings",0).edit().putString("lastBook","old-local-book").commit();ServerBridge.rememberLatest(c,bid);check(c.getSharedPreferences("settings",0).getString("lastBook","").equals(bid),"Global latest book replaces a different local continue target");
  ServerBridge.prefs(c).edit().putString("latest_local_event","new-event").commit();ServerBridge.positionStatus(c,"old-event","Incorrect acknowledgement");check(!ServerBridge.visibleStatus(c).equals("Incorrect acknowledgement"),"An older upload cannot acknowledge the latest pending position");ServerBridge.positionStatus(c,"new-event","Position acknowledged");check(ServerBridge.visibleStatus(c).equals("Position acknowledged"),"Current acknowledgement is persisted for visible feedback");
 }
 void profileAndRetention(Context c)throws Exception{
  Store store=Store.get(c);String bid="truyen-999889",url="https://docln.sbs/truyen/999889-fixture";store.putBook(new HakoParser.Link(bid,"Read trial",url));store.catalog(bid,Arrays.asList(new HakoParser.Link(bid+"-1","Chapter",url+"/c1-text")));Store.write(store.html(bid+"-1"),"<p>Read trial is retained after leaving the reader.</p>");store.clearTemporary(bid);store.prune(store.book(bid));check(store.html(bid+"-1").isFile(),"Leaving a trial and default pruning preserve local text");
  c.getSharedPreferences("settings",0).edit().putBoolean("eink_mode",true).commit();org.json.JSONObject doc=new org.json.JSONObject().put("kind","text").put("html","<p>Text only retained.</p><img src='https://cdn.invalid/no-download.png'>").put("images",new org.json.JSONArray().put(new org.json.JSONObject().put("name","not-a-valid-image-name")));
  Repository.activeBook=bid;ServerSource.save(c,store.chapter(bid,bid+"-1"),doc);Repository.activeBook="";check(!Store.read(store.html(bid+"-1")).contains("<img"),"S4 stores text without requesting or decoding image descriptors");check(store.missingImages(bid+"-1")==0,"S4 never reports missing color illustrations");
  NativeReader.Prepared prepared=NativeReader.prepare("<p>Text before image</p><img src='https://offline.hako.invalid/image-test.bin'><p>Text after image</p>",c.getFilesDir(),1,480,800,8,9,false);check(prepared.text.getSpans(0,prepared.text.length(),android.text.style.ImageSpan.class).length==0&&prepared.text.toString().contains("Text after image"),"Text-only reader keeps text and has no image spans");
  runOnMainSync(()->{BookUi.Flow tags=BookUi.flow(c);BookUi.tag(tags,"Long Vietnamese label with several words to wrap safely");BookUi.tag(tags,"Next tag");tags.measure(View.MeasureSpec.makeMeasureSpec(200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));tags.layout(0,0,200,tags.getMeasuredHeight());for(int i=0;i<tags.getChildCount();i++){View child=tags.getChildAt(i);check(child.getRight()<=200&&child.getBottom()<=tags.getHeight(),"Wrapping tags remain inside the measured viewport");}});
  c.getSharedPreferences("settings",0).edit().putBoolean("eink_mode",false).commit();
 }
 void swipe(NativeReader reader,float x,float y,float endX,float endY){long t=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_MOVE,MotionEvent.ACTION_UP}){MotionEvent event=MotionEvent.obtain(t,t+(action==0?0:100),action,action==0?x:endX,action==0?y:endY,0);reader.onTouchEvent(event);event.recycle();}}
}
